   130	                    return Err(format!("action duration must be positive, not {given}"));
   131	                }
   132	                snapped
   133	            }
   134	        };
   135	        if at.saturating_add(duration) > target.duration {
   136	            return Ok(Outcome::Refused(action_past_end(
   137	                clip,
   138	                at,
   139	                duration,
   140	                target.duration,
   141	            )));
   142	        }
   143	        if let Some(other) = overlapping_action(&target.actions, None, at, duration) {
   144	            return Ok(Outcome::Refused(action_overlaps(clip, other)));
   145	        }
