   150	            slot.actions.push(Action {
   151	                id,
   152	                start: at,
   153	                duration,
   154	                curve: Curve::default(),
   155	                end: Value::Object(serde_json::Map::new()),
   156	            });
   157	        }
   158	        self.finish(next)
