   161	    /// Retimes or re-curves one action; every argument left `None` keeps
   162	    /// its current value (spec §6). The same overlap check as `add_action`;
   163	    /// the clip-end check refuses ([`action_past_end`]) only an edit that
   164	    /// ends the action past the clip's end AND later than it ended before
   165	    /// (spec §11 SR-22, #338), so an action already running past the end —
   166	    /// a trim or a ramp scale leaves one there — can be re-curved, moved
   167	    /// earlier or shortened, and one inside the clip still cannot be pushed
   168	    /// past it.
   169	    pub fn set_action(
   170	        &self,
   171	        clip: u32,
   172	        action: u32,
   173	        start: Option<Ticks>,
   174	        duration: Option<Ticks>,
   175	        curve: Option<Curve>,
   176	    ) -> Result<Outcome, String> {
   177	        let target = self.require_clip(clip)?.clone();
   178	        let existing = target
   179	            .actions
   180	            .iter()
   181	            .find(|a| a.id == action)
   182	            .ok_or_else(|| format!("no action with id {action} on clip {clip}"))?
   183	            .clone();
   184	
   185	        let new_start = match start {
   186	            None => existing.start,
   187	            Some(given) => {
   188	                let snapped = self.snapped(given);
   189	                if snapped < 0 {
   190	                    return Err(format!("action start must not be negative, not {given}"));
   191	                }
   192	                snapped
   193	            }
   194	        };
   195	        let new_duration = match duration {
   196	            None => existing.duration,
   197	            Some(given) => {
   198	                let snapped = self.snapped(given);
   199	                if snapped <= 0 {
   200	                    return Err(format!("action duration must be positive, not {given}"));
   201	                }
   202	                snapped
   203	            }
   204	        };
   205	        let new_end = new_start.saturating_add(new_duration);
   206	        let old_end = existing.start.saturating_add(existing.duration);
   207	        if new_end > target.duration && new_end > old_end {
   208	            return Ok(Outcome::Refused(action_past_end(
   209	                clip,
   210	                new_start,
   211	                new_duration,
   212	                target.duration,
   213	            )));
   214	        }
   215	        if let Some(other) =
   216	            overlapping_action(&target.actions, Some(action), new_start, new_duration)
   217	        {
   218	            return Ok(Outcome::Refused(action_overlaps(clip, other)));
   219	        }
   220	
   221	        let mut next = self.clone();
   222	        if let Some(slot) = next
   223	            .clip_mut(clip)
   224	            .and_then(|c| c.actions.iter_mut().find(|a| a.id == action))
   225	        {
   226	            slot.start = new_start;
   227	            slot.duration = new_duration;
   228	            if let Some(curve) = curve {
   229	                slot.curve = curve;
   230	            }
   231	        }
   232	        // A linked clip's rate is refused (spec §11 AU-94).
   233	        if let Some(why) = next
   234	            .clip(clip)
   235	            .and_then(|after| self.linked_rate_refusal(&target, after))
   236	        {
   237	            return Ok(Outcome::Refused(why));
   238	        }
   239	        // A rate action moves the out point when it moves (SR-2).
   240	        if end_speed(&existing).is_some() {
   241	            let what = format!("retiming action {action}");
   242	            if let Some(why) = next.clip(clip).and_then(|c| self.overrun_refusal(c, &what)) {
   243	                return Ok(Outcome::Refused(why));
   244	            }
   245	        }
   246	        self.finish(next)
   247	    }
   248	
   249	    /// Merges `patch` into the action's end state; a key set to `null`
   250	    /// REMOVES it, which is how the inspector stops animating one property
   251	    /// without deleting the action (spec §6).
   252	    ///
   253	    /// The patch is walked like every other one (`patch.rs`'s
   254	    /// `check_end_patch`): an unknown key, a value of the wrong JSON kind
   255	    /// and a misspelt variant are each refused, naming the dotted path with
   256	    /// the group's name in it and the value sent. What it does NOT do is
   257	    /// range-check — the state a clip interpolates toward may legitimately
   258	    /// name a value no stored group could hold, and `actions_clamp.rs`'s
   259	    /// `clamp_video`, `clamp_audio` and `clamp_text` bound the evaluated
   260	    /// value instead (spec §5.4); a graphic prop's end is the exception,
   261	    /// checked against the op's `schema` (G-34 (c)).
   262	    ///
   263	    /// A `null` is the one value the walk lets past at any depth, because
   264	    /// here it is a REMOVAL rather than a clear.
   265	    ///
   266	    /// The refusal that is about this op rather than about the vocabulary:
   267	    /// a `video` object naming `motion` is an `Err`. A preset is anchored to
   268	    /// the clip's two ends and an action is a ramp between two states, so
   269	    /// there is nothing to interpolate — half a slide into half a spin is
   270	    /// not a picture anybody asked for — and the evaluator would put the
   271	    /// base value back anyway, leaving a control that reported success and
   272	    /// did nothing. A `text` object naming `words` is an `Err` too (format
   273	    /// version 9, spec §11 W-6): a word's times are anchored to speech, not
   274	    /// a state a clip ramps toward, and interpolating two lists of ticks
   275	    /// would move every word off what it times. A `video.cutout` naming
   276	    /// `subject` or `quality`, a `null` included, is an `Err` as well
   277	    /// ([`check_cutout_end`], spec §11 CO-20): both are the clip's base.
   278	    ///
   279	    /// `off` (spec §11 CI-14) is the one way to STORE a `null`: each
   280	    /// `"group.key"` path is written as `null` after the merge and the
   281	    /// prune, which keys that optional property off at the action's end.
   282	    /// It refuses what `patch` refuses ([`check_off`]).
   283	    ///
   284	    /// `graphic` is `edit_action_graphic.rs`'s (G-34), read against
   285	    /// `schema`; a prop the clip's map lacks gets its start in this edit.
   286	    pub fn set_action_end(
   287	        &self,
   288	        clip: u32,
   289	        action: u32,
   290	        patch: &Value,
   291	        off: &[String],
   292	        schema: Option<&Value>,
   293	    ) -> Result<Outcome, String> {
   294	        let target = self.require_clip(clip)?;
   295	        let existing = target
   296	            .actions
   297	            .iter()
   298	            .find(|a| a.id == action)
   299	            .ok_or_else(|| format!("no action with id {action} on clip {clip}"))?;
   300	        if !patch.is_object() {
   301	            return Err(format!(
   302	                "action end patch must be a json object, not {}",
   303	                describe(patch)
   304	            ));
   305	        }
   306	        if let Some(schema) = schema {
   307	            check_schema(schema)?;
   308	        }
   309	        // Present at all — a `null` included, since writing `motion: null`
   310	        // into an end patch is still asking an action to decide a preset.
   311	        for (group, key) in [
   312	            ("video", "motion"),
   313	            ("video", "hide_silent"),
   314	            ("text", "words"),
   315	        ] {
   316	            if patch.get(group).and_then(|body| body.get(key)).is_some() {
   317	                not_a_target(group, key)?;
   318	            }
   319	        }
   320	        check_cutout_end(patch)?;
   321	        check_end_patch(patch)?;
   322	        let graphic = match patch.get("graphic") {
   323	            Some(body) => Some(read_graphic_end(target, body, schema)?),
   324	            None => None,
   325	        };
   326	        let speed = match patch.get("speed") {
   327	            Some(value) => Some(read_speed_end(target, value)?),
   328	            None => None,
   329	        };
   330	        let off = check_off(patch, off)?;

