     3	/// The selected action — the sixth piece of view state (spec §11 CI-1): nil,
     4	/// or ONE action of the SINGLE selected clip. Like the other five it is not
     5	/// undoable, not persisted and has no MCP mirror; agents address actions by
     6	/// id through the action ops, which is the whole capability.
     7	///
     8	/// Three writers and no others: `selectAction(_:)` below (the lane, the
     9	/// timeline's bands, esc, the Clip chip, an add), `syncSelectedAction()`
    10	/// (the playhead ENTERING a span), and `clampViewState`, which drops an id
    11	/// the edited project no longer has on the selected clip.
    12	///
    13	/// **Entry, not presence.** `lastInsideAction` is the span the playhead was
    14	/// last inside, so a sync selects only on a CHANGE of span: after esc the
    15	/// playhead can sit inside one without re-selecting it until it leaves and
    16	/// comes back, and leaving a span keeps the selection. An edit never enters
    17	/// one — `clampViewState` re-reads `lastInsideAction` before its own
    18	/// playhead write, so a redo, a live drag or an add that puts a span under a
    19	/// stationary playhead selects nothing.
    20	///
    21	/// The stored pair lives in `ProjectDocument.swift` because an extension
    22	/// cannot add stored properties (`+DisplayStem`'s precedent for the split);
    23	/// the queries and the entry rule live here, where the size rule wants them.
    24	extension ProjectDocument {
    25	    /// The edited project's clip when exactly one clip is selected.
    26	    var singleSelectedClip: ClipSnapshot? {
    27	        guard selection.count == 1, let id = selection.first else { return nil }
    28	        return editedProject.snapshot.clip(id)
    29	    }
    30	
    31	    /// The single selected clip's action with `start ≤ clipTime(playhead) <
    32	    /// endTime`. Actions on one clip never overlap, so there is at most one.
    33	    var actionUnderPlayhead: ActionSnapshot? {
    34	        guard let clip = singleSelectedClip else { return nil }
    35	        let t = clip.clipTime(playhead)
    36	        return clip.actions.first { $0.start <= t && t < $0.endTime }
    37	    }
    38	
    39	    /// The selected action's snapshot, read fresh from the edited project —
    40	    /// nil when nothing is selected or the id is no longer the clip's.
    41	    var selectedActionSnapshot: ActionSnapshot? {
    42	        guard let id = selectedAction else { return nil }
    43	        return singleSelectedClip?.actions.first { $0.id == id }
    44	    }
    45	
    46	    /// The entry rule. Called from `playhead`'s and `selection`'s `didSet`.
    47	    func syncSelectedAction() {
    48	        let under = actionUnderPlayhead?.id
    49	        guard under != lastInsideAction else { return }
    50	        lastInsideAction = under
    51	        if let under { selectedAction = under }
    52	    }
    53	
    54	    /// The one deliberate writer. An id that is not the single selected
    55	    /// clip's is stored as nil, so a multi-selection never holds one; the
    56	    /// span under the playhead is recorded as already entered, so the next
    57	    /// sync does not overrule the choice.
    58	    func selectAction(_ id: UInt32?) {
    59	        let owned = singleSelectedClip?.actions.contains { $0.id == id } == true
    60	        selectedAction = owned ? id : nil
    61	        lastInsideAction = actionUnderPlayhead?.id
    62	    }
    63	}
import AppKit

/// The row marks of the Clip inspector (road map 9 §5, spec §11 CI-7): what
/// the SELECTED action does to one row, in a 14 pt gutter before its label.
///
/// A row's mark is derived from two lists of `"group.key"` paths: the keys
/// its control WRITES — taken from the row's own `ops(read())` at build time,
/// so a write that lands on the action's end patch and one that lands on the
/// base props name the same key — and the keys it only FOLLOWS (Gain follows
/// Volume). Both empty is `.none`, action or no action: a row that says
/// nothing about what it writes (a readout, a Document-tab row) is never
/// marked ⊘ by omission.
enum RowMark: Equatable {
    /// Nothing to say — the gutter stays blank.
    case none
    /// ◆ — the row writes a key the selected action's end patch holds.
    case keyed
    /// ◆ and "at end" — the same, for a discrete control, which switches at
    /// the action's end rather than ramping.
    case keyedAtEnd
    /// ◇ — ANOTHER action keys it; the number is that action's time-order
    /// number (`ActionBands.ordered`).
    case other(Int)
    /// ○ — the row follows a keyed value without writing it.
    case follows
    /// ⊘ — the row writes the clip whatever is selected (CI-3, motion, a
    /// list's length): the selected action cannot animate it.
    case notAnimatable
}

/// A section's marks, folded from its gutters: how many KEYS its rows write
/// that the selected action holds (CI-6's count, so a section's `◆N` agrees
/// with its sub-tab's), whether any row is ◇, whether every row that writes
/// is ⊘, whether the section differs from its default (spec §11 CI-9), and
/// the number of the action it is EDITING — the selected one, when any of
/// its rows animates — which is what turns its Reset slot into Clear.
struct SectionMarks: Equatable {
    var keyed: Int
    var other: Bool
    var allNotAnimatable: Bool
    var differs = false
    var editing: Int? = nil

    static let empty = SectionMarks(keyed: 0, other: false, allNotAnimatable: false)
}

/// A row's default (spec §11 CI-9): the undo name its reset runs under,
/// whether the row differs from its default now, and the ops that put the
/// default back — on the base props, or on the selected action's end.
struct InspectorRowDefault {
    let name: String
    let differs: () -> Bool
    let ops: () -> [ReelOp]

    /// The default a typed row derives from its own `read` and `ops`: the
    /// value `read` answers in `.defaults`, written through `ops`.
    static func derived<T: Equatable>(
        _ binding: InspectorBinding, name: String, read: @escaping () -> T,
        ops: @escaping (T) -> [ReelOp]
    ) -> InspectorRowDefault {
    override var isFlipped: Bool { true }

    /// The keys this row writes that the selected action holds — what a
    /// section's `◆N` is the union of.
    func keyedWrites() -> Set<String> {
        guard let binding else { return [] }
        return binding.keyedPaths().intersection(writes)
    }

    /// Takes the row's keys out of the selected action's end patch — the ×
    /// and the menu's "Remove from action N".
    func removeFromAction() {
        guard let binding else { return }
        binding.apply("Remove from Action", binding.clearOps(keyedWrites()))
    }

    func refresh() {
        let next = binding?.mark(
            writes: writes, follows: follows, animates: animates, discrete: discrete) ?? .none
        if next != mark {
            mark = next
            needsDisplay = true
        }
        let ink = isKeyed ? DS.textStrong : mark == .notAnimatable ? DS.textFaint : DS.textMuted
        if let label, label.textColor != ink { label.textColor = ink }
        updateToolTip()
        paintBorders()
    }

    private func updateToolTip() {
        if showsRemove, let number = binding?.selectedActionNumber {
            toolTip = "Remove from action \(number)"
        } else if case .other(let number) = mark {
            toolTip = "Changed by action \(number)"
        } else {
            toolTip = nil
        }
    }

    /// The keyed rows' 1 pt action-ink border on their fields and popups.
    private func paintBorders() {
        let keyed = isKeyed
        for control in controls where control is OptionFieldControl
            || control is OptionPopupControl
        {
            if keyed { control.wantsLayer = true }
            guard let layer = control.layer else { continue }
            layer.borderWidth = keyed ? 1 : 0
            if keyed {
                effectiveAppearance.performAsCurrentDrawingAppearance {
                    layer.borderColor = DS.action.cgColor
                }
            }
        }
    }

    /// A `CGColor` does not follow the appearance, so the border is resolved
    /// again when it changes.
    override func viewDidChangeEffectiveAppearance() {
        super.viewDidChangeEffectiveAppearance()
        paintBorders()
    }

    override func mouseDown(with event: NSEvent) {
        guard showsRemove else {
            super.mouseDown(with: event)
            return
        }
        removeFromAction()
    }

    override func draw(_ dirtyRect: NSRect) {
        let glyph: String
        let ink: NSColor
        switch mark {
        case .none: return
        case .keyed, .keyedAtEnd:
            (glyph, ink) = showsRemove ? ("×", DS.textMuted) : ("◆", DS.action)
        case .follows: (glyph, ink) = ("○", DS.action)
        case .other: (glyph, ink) = ("◇", DS.textFaint)
        case .notAnimatable: (glyph, ink) = ("⊘", DS.textFaint)
        }
        let attributes: [NSAttributedString.Key: Any] = [.font: DS.mono(10), .foregroundColor: ink]
        let size = glyph.size(withAttributes: attributes)
        glyph.draw(
            at: NSPoint(x: (bounds.width - size.width) / 2, y: (bounds.height - size.height) / 2),
            withAttributes: attributes)
    }
}

/// A short mono tag after a row's controls — "at end" in the action ink, or
/// the coral "now …" of a field-only row. Hidden while `text` answers nil.
final class InspectorRowTag: NSTextField, OptionControl {
    private let text: () -> String?

    init(text: @escaping () -> String?, color: NSColor) {
        self.text = text
        super.init(frame: .zero)
        isEditable = false
        isBordered = false
        isBezeled = false
        drawsBackground = false
        font = DS.mono(10)
        textColor = color
        // One line: a wrapping tag gives its width away to its neighbours by
        // growing tall, so a row short of room squeezed "at end" into a
        // column instead of narrowing the field beside it (B87, G-34 (l)).
        maximumNumberOfLines = 1
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorRowTag does not support NSCoder")
    }

    func refresh() {
        let next = text()
        if stringValue != (next ?? "") { stringValue = next ?? "" }
        isHidden = next == nil
    }
        return true
    }

    func refresh() {
        refreshOptionControls(in: content)
        foldMarks()
    }

    /// The header's Clear (spec §11 CI-9): every key the section's rows
    /// write that the selected action holds, out of its end patch in ONE
    /// `set_action_end`.
    func clear() {
        let gutters = Self.gutters(in: content)
        guard let binding = gutters.lazy.compactMap({ $0.binding }).first else { return }
        let keys = gutters.reduce(into: Set<String>()) { $0.formUnion($1.keyedWrites()) }
        binding.apply("Clear", binding.clearOps(keys))
    }

    /// The rows' gutters, in the order `refreshOptionControls(in:)` walks.
    private static func gutters(in view: NSView) -> [InspectorMarkGutter] {
        view.subviews.flatMap { subview -> [InspectorMarkGutter] in
            if let gutter = subview as? InspectorMarkGutter { return [gutter] }
            return gutters(in: subview)
        }
    }

    /// `marks` from the gutters as they stand, then the two things drawn from
    /// it: the ⊘ note and the header. A section is EDITING the selected
    /// action when any of its rows animates; one that none does (Document,
    /// Shape, a ⊘-only section) keeps its Reset, since its edits go to the
    /// clip.
    private func foldMarks() {
        let gutters = Self.gutters(in: content)
        let writing = gutters.filter { !$0.writes.isEmpty }
        let binding = gutters.lazy.compactMap { $0.binding }.first
        marks = SectionMarks(
            keyed: gutters.reduce(into: Set<String>()) { $0.formUnion($1.keyedWrites()) }.count,
            other: gutters.contains {
                if case .other = $0.mark { return true } else { return false }
            },
            allNotAnimatable: !writing.isEmpty
                && writing.allSatisfy { $0.mark == .notAnimatable },
            differs: differs?() ?? gutters.contains { $0.default?.differs() == true },
            editing: gutters.contains { $0.animates } ? binding?.selectedActionNumber : nil)
        inertNote?.refresh()
        header.refresh(summary: summary?(), marks: marks)
    }
}

/// The auto-open (spec §11 CI-8): the sections the selected action keys are
/// revealed on the sub-tab showing them, remembered for as long as that
/// action stays selected — so a rebuild under the same action re-reveals
/// them, a sub-tab first shown later adds its own, and a header click that
/// closes one drops it. One per `ClipPane`, applied at the end of every
/// `makeSections()`; it lives here because `ClipPane.swift` is at its cap.
final class KeyedReveal {
    private(set) var action: UInt32?
    private(set) var seen: Set<String> = []
    private(set) var ids: Set<String> = []

    func apply(_ sections: [InspectorSection], action: UInt32?, subTab: String) {
        guard let action else {
            (self.action, seen, ids) = (nil, [], [])
            return
        }
        if action != self.action { (self.action, seen, ids) = (action, [], []) }
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: NSView.noIntrinsicMetric, height: InspectorMetrics.headerHeight)
    }

    func configure(title: String, reset: (() -> Void)?, clear: @escaping () -> Void) {
        self.title = title
        clearButton = install(
            OptionButtonControl(title: "Clear", action: clear, enabled: { true }, onEdit: {}))
        if let reset {
            let button = install(
                OptionButtonControl(title: "Reset", action: reset, enabled: { true }, onEdit: {}))
            button.toolTip = "Reset this section to its defaults"
            resetButton = button
        }
        showButtons()
    }

    private func install(_ button: NSView) -> NSView {
        button.translatesAutoresizingMaskIntoConstraints = false
        addSubview(button)
        NSLayoutConstraint.activate([
            button.trailingAnchor.constraint(
                equalTo: trailingAnchor, constant: -InspectorMetrics.inset),
            button.centerYAnchor.constraint(equalTo: centerYAnchor),
        ])
        return button
    }

    /// CI-9's one slot: Clear while editing an action that keys the section,
    /// Reset while not editing and the section differs, else nothing.
    private func showButtons() {
        let editing = marks.editing
        clearButton?.isHidden = editing == nil || marks.keyed == 0
        clearButton?.toolTip = editing.map { "Remove this section from action \($0)" }
        resetButton?.isHidden = editing != nil || !marks.differs
    }

    /// The visible button's title — "Clear", "Reset" or nil.
    var buttonTitle: String? {
        if clearButton?.isHidden == false { return "Clear" }
        if resetButton?.isHidden == false { return "Reset" }
        return nil
    }

    /// The summary's ink: the action's when keyed, the body tier
    /// (`DS.textMuted`, spec §11 CI-9) when the section differs from its
    /// default, else faint.
    var summaryInk: NSColor {
        marks.keyed > 0 ? DS.action : marks.differs ? DS.textMuted : DS.textFaint
    }

    /// Takes the summary and the marks; redraws only when either moved.
/// drag writes the rail's own range.
func inspectorValueRow(
    _ label: String, _ binding: InspectorBinding, name: String, unit: String = "",
    decimals: Int = 0, min lower: Double, max upper: Double, sliderMax: Double? = nil,
    quick: [Double] = [],
    slider: Bool = true, width: CGFloat = InspectorMetrics.fieldWidth,
    read: @escaping () -> Double, ops: @escaping (Double) -> [ReelOp],
    mixed: (() -> Bool)? = nil, enabled: @escaping () -> Bool = { true },
    resets: Bool = true
) -> NSView {
    var controls: [NSView] = []
    let track = slider ? InspectorSliderControl(
        min: lower, max: sliderMax ?? upper, read: read,
        write: { [weak binding] value in binding?.liveUpdate(ops(value)) },
        begin: { [weak binding] in binding?.liveBegin() },
        end: { [weak binding] in binding?.liveEnd(name) },
        enabled: enabled,
        start: { [weak binding] in binding?.startValue(read) },
        now: { [weak binding] in binding?.nowValue(read) }) : nil
    if let track { controls.append(track) }
    controls.append(
        OptionFieldControl(
